{
  "ID": "GRAV-UNIFORM",
  "VERSION": "1.0.0",
  "TITLE": "Uniform gravity at the standard value g_n",
  "SOURCE": "g_n = 9.80665 m s-2, exact by definition: 3rd CGPM (1901), declaration on the unit of mass and on the definition of weight",
  "PREREQUISITES": [
    {
      "SLOT": "MASS",
      "KIND": "CONSTANT",
      "DIMENSION": "M1",
      "MIN": 1,
      "MAX": 1,
      "LABEL": "the mass of the body"
    },
    {
      "SLOT": "UP_VELOCITY",
      "KIND": "DOF",
      "DIMENSION": "L1 T-1",
      "MIN": 1,
      "MAX": 1,
      "LABEL": "the velocity component pointing up; its equation of motion receives the weight"
    },
    {
      "SLOT": "HEIGHT",
      "KIND": "DOF",
      "DIMENSION": "L1",
      "MIN": 1,
      "MAX": 1,
      "LABEL": "the position along the same upward axis"
    }
  ],
  "PARAMETERS": [
    {
      "NAME": "g_n",
      "DIMENSION": "L1 T-2",
      "SUPPLY": "DECLARED",
      "VALUE": "9.80665",
      "UNIT": "m s-2",
      "OVERRIDABLE": "NO",
      "LABEL": "the standard acceleration of gravity"
    },
    {
      "NAME": "h_max",
      "DIMENSION": "L1",
      "SUPPLY": "AUTHOR",
      "LABEL": "the largest height, above or below the origin, over which the field is taken as uniform"
    }
  ],
  "SUMS": [],
  "TERMS": [
    {
      "TARGET": "UP_VELOCITY",
      "SIGN": "-",
      "EXPR": "MASS*g_n",
      "LABEL": "the weight"
    }
  ],
  "ASSUMPTIONS": [
    {
      "NAME": "gravity_uniform",
      "PROPOSITION": "the gravitational field is uniform over the region abs({HEIGHT}) < h_max",
      "REFS": [
        "HEIGHT",
        "h_max"
      ]
    },
    {
      "NAME": "gravity_standard",
      "PROPOSITION": "the local gravitational acceleration equals the conventional standard value g_n",
      "REFS": [
        "g_n"
      ]
    },
    {
      "NAME": "frame_inertial",
      "PROPOSITION": "the frame in which {HEIGHT} is measured is treated as inertial",
      "REFS": [
        "HEIGHT"
      ]
    }
  ],
  "BOUNDARIES": [
    {
      "NAME": "gravity_region",
      "PREDICATE": "abs({HEIGHT}) < h_max",
      "CONDITION": "abs(HEIGHT) < h_max"
    }
  ],
  "NOT_CHOSEN": "No gravity: no weight acts on any DOF.",
  "NOT_INCLUDED": [
    "No variation of gravity with height or latitude beyond what g_n contains.",
    "No Earth rotation (Coriolis or centrifugal force) beyond what g_n contains.",
    "No gravity of bodies other than the Earth."
  ],
  "EXCLUDES": [],
  "INTERACTS_WITH": [
    {
      "WITH": "AIR-*",
      "QUESTION_ID": "BUOYANCY",
      "QUESTION": "Does the air's buoyancy (upthrust) act on the body in the system you mean?",
      "YES_LINE": "Buoyancy acts (your answer): no module adds it; it acts in this kernel only where one of your own laws states it.",
      "NO_LINE": "No buoyancy: the air's upthrust on the body is not included."
    }
  ],
  "TEST_BINDINGS": [
    {
      "NAME": "PROJECTILE_2D",
      "TPK": {
        "DOF": [
          {
            "NAME": "t",
            "DIMENSION": "T1"
          },
          {
            "NAME": "x",
            "DIMENSION": "L1"
          },
          {
            "NAME": "z",
            "DIMENSION": "L1"
          },
          {
            "NAME": "v_x",
            "DIMENSION": "L1 T-1"
          },
          {
            "NAME": "v_z",
            "DIMENSION": "L1 T-1"
          }
        ],
        "CONSTANT": [
          {
            "NAME": "m",
            "DIMENSION": "M1"
          }
        ],
        "LAW": [
          {
            "NAME": "KIN_X",
            "STATEMENT": "dx/dt = v_x",
            "REFS": [
              "t",
              "v_x",
              "x"
            ],
            "ROLE": "EOM(x)",
            "EQUATION": "D(x,t)=v_x"
          },
          {
            "NAME": "KIN_Z",
            "STATEMENT": "dz/dt = v_z",
            "REFS": [
              "t",
              "v_z",
              "z"
            ],
            "ROLE": "EOM(z)",
            "EQUATION": "D(z,t)=v_z"
          },
          {
            "NAME": "EOM_X",
            "STATEMENT": "m dv_x/dt = 0",
            "REFS": [
              "m",
              "t",
              "v_x"
            ],
            "ROLE": "EOM(v_x)",
            "EQUATION": "m*D(v_x,t)=0"
          },
          {
            "NAME": "EOM_Z",
            "STATEMENT": "m dv_z/dt = 0",
            "REFS": [
              "m",
              "t",
              "v_z"
            ],
            "ROLE": "EOM(v_z)",
            "EQUATION": "m*D(v_z,t)=0"
          }
        ],
        "ASSUMPTION": [
          {
            "NAME": "point_mass",
            "PROPOSITION": "the body is treated as a point mass",
            "REFS": [
              "m"
            ]
          }
        ]
      },
      "BIND": {
        "HEIGHT": [
          "z"
        ],
        "MASS": [
          "m"
        ],
        "UP_VELOCITY": [
          "v_z"
        ]
      },
      "VALUES": {
        "h_max": {
          "VALUE": "100",
          "UNIT": "m"
        }
      },
      "ANSWERS": {}
    },
    {
      "NAME": "TABLE",
      "TPK": {
        "DOF": [
          {
            "NAME": "t",
            "DIMENSION": "T1"
          },
          {
            "NAME": "x",
            "DIMENSION": "L1"
          },
          {
            "NAME": "z",
            "DIMENSION": "L1"
          },
          {
            "NAME": "v_x",
            "DIMENSION": "L1 T-1"
          },
          {
            "NAME": "v_z",
            "DIMENSION": "L1 T-1"
          }
        ],
        "CONSTANT": [
          {
            "NAME": "m",
            "DIMENSION": "M1"
          }
        ],
        "LAW": [
          {
            "NAME": "KIN_X",
            "STATEMENT": "dx/dt = v_x",
            "REFS": [
              "t",
              "v_x",
              "x"
            ],
            "ROLE": "EOM(x)",
            "EQUATION": "D(x,t)=v_x"
          },
          {
            "NAME": "KIN_Z",
            "STATEMENT": "dz/dt = v_z",
            "REFS": [
              "t",
              "v_z",
              "z"
            ],
            "ROLE": "CONSTRAINT",
            "EQUATION": "D(z,t)=v_z"
          },
          {
            "NAME": "EOM_X",
            "STATEMENT": "m dv_x/dt = 0",
            "REFS": [
              "m",
              "t",
              "v_x"
            ],
            "ROLE": "EOM(v_x)",
            "EQUATION": "m*D(v_x,t)=0"
          }
        ],
        "CONSTRAINT": [
          {
            "NAME": "C_Z",
            "TARGET": "z",
            "ACTION": "FIX",
            "VALUE": "0",
            "UNIT": "m",
            "STATEMENT": "the puck stays on the table top, z = 0"
          },
          {
            "NAME": "C_VZ",
            "TARGET": "v_z",
            "ACTION": "FIX",
            "VALUE": "0",
            "UNIT": "m s-1",
            "STATEMENT": "the puck has no vertical velocity"
          }
        ]
      },
      "BIND": {
        "HEIGHT": [
          "z"
        ],
        "MASS": [
          "m"
        ],
        "UP_VELOCITY": [
          "v_z"
        ]
      },
      "VALUES": {
        "h_max": {
          "VALUE": "1",
          "UNIT": "m"
        }
      },
      "ANSWERS": {
        "FIXED:v_z": "YES"
      }
    }
  ]
}

